+/**
+ * B.2 parity test — both write paths (computeAndPersistMatches and
+ * persistSessionMatches) must write the same 21 columns. This test verifies
+ * that createMatch accepts and stores all fields so neither path leaves gaps.
+ *
+ * We can't run computeAndPersistMatches in-process (it calls an LLM scorer),
+ * so we call createMatch directly with the same input shape both paths produce
+ * and assert all 21 data columns are stored correctly.
+ */
+import Database from 'better-sqlite3';
+import migration032 from '@/lib/migrations/032-matches';
+import migration033 from '@/lib/migrations/033-matches-score-breakdown';
+import migration034 from '@/lib/migrations/034-matches-unique-constraint';
+import migration035 from '@/lib/migrations/035-matches-tce-distance';
+import migration036 from '@/lib/migrations/036-matches-freight-rate';
+import migration041 from '@/lib/migrations/041-matches-vessel-name';
+import migration042 from '@/lib/migrations/042-matches-fit';
+import migration044 from '@/lib/migrations/044-matches-item-index';
+import migration045 from '@/lib/migrations/045-matches-worksheet';
+import migration046 from '@/lib/migrations/046-matches-consumption-estimated';
+import migration047 from '@/lib/migrations/047-matches-ballast-distance';
+import migration050 from '@/lib/migrations/050-matches-breakeven';
+import { createMatch, getMatch } from '@/lib/matching/matches-repository';
+
+function freshDb(): Database.Database {
+  const db = new Database(':memory:');
+  migration032.up(db);
+  migration033.up(db);
+  migration034.up(db);
+  migration035.up(db);
+  migration036.up(db);
+  migration041.up(db);
+  migration042.up(db);
+  migration044.up(db);
+  migration045.up(db);
+  migration046.up(db);
+  migration047.up(db);
+  migration050.up(db);
+  return db;
+}
+
+const FULL_INPUT = {
+  cargo_id: 'cargo-parity-01',
+  vessel_id: 'vessel-parity-01',
+  score: 83,
+  reason: 'Good timing and DWT fit',
+  status: 'shortlist' as const,
+  user_id: 'session-parity',
+  reason_structured: null,
+  cargo_type: 'grain',
+  load_port: 'Rotterdam',
+  discharge_port: 'Constanta',
+  laycan_start: 1_750_000_000_000,
+  laycan_end: 1_750_500_000_000,
+  vessel_dwt: 57_000,
+  tce_usd_per_day: 12_500,
+  distance_nm: 1_850,
+  freight_rate_usd_per_mt: 22.5,
+  freight_rate_source: 'estimated',
+  vessel_name: 'M/V SEAGULL 200',
+  cargo_ref: 'Grain 50kt test',
+  fit_percent: 79,
+  fit_breakdown: JSON.stringify({ fitPercent: 79, components: [] }),
+  cargo_item_index: 0,
+  vessel_item_index: 1,
+  worksheet_json: JSON.stringify({ readiness: { verdict: 'ideal' }, vessel: {}, cargo: {}, hardFilters: {} }),
+  consumption_estimated: 0,
+  ballast_distance_nm: 320,
+  breakeven_tce_usd_per_day: 8_000,
+};
+
+const PARITY_COLS = [
+  'cargo_id', 'vessel_id', 'score', 'reason', 'status', 'user_id',
+  'cargo_type', 'load_port', 'discharge_port',
+  'laycan_start', 'laycan_end', 'vessel_dwt',
+  'tce_usd_per_day', 'distance_nm',
+  'freight_rate_usd_per_mt', 'freight_rate_source',
+  'vessel_name', 'cargo_ref',
+  'fit_percent', 'fit_breakdown',
+  'cargo_item_index', 'vessel_item_index',
+  'worksheet_json',
+  'consumption_estimated', 'ballast_distance_nm',
+  'breakeven_tce_usd_per_day',
+] as const;
+
+describe('write-path parity — createMatch stores all 21+ columns (B.2)', () => {
+  it('stores all parity columns when full input is provided', () => {
+    const db = freshDb();
+    const row = createMatch(db, FULL_INPUT);
+    const fetched = getMatch(db, row.id);
+    expect(fetched).not.toBeNull();
+
+    for (const col of PARITY_COLS) {
+      expect({ col, value: fetched![col as keyof typeof fetched] }).not.toEqual(
+        { col, value: null },
+      );
+    }
+  });
+
+  it('reason_structured is null for both paths (B.1 invariant)', () => {
+    const db = freshDb();
+    const row = createMatch(db, { ...FULL_INPUT, cargo_id: 'cargo-b1', vessel_id: 'vessel-b1', reason_structured: null });
+    const fetched = getMatch(db, row.id);
+    expect(fetched!.reason_structured).toBeNull();
+  });
+
+  it('refreshComputed updates economics + fit on duplicate without touching status', () => {
+    const db = freshDb();
+    createMatch(db, { ...FULL_INPUT, cargo_id: 'cargo-refresh', vessel_id: 'vessel-refresh', status: 'saved', tce_usd_per_day: 10_000 });
+
+    createMatch(db, {
+      ...FULL_INPUT,
+      cargo_id: 'cargo-refresh',
+      vessel_id: 'vessel-refresh',
+      tce_usd_per_day: 15_000,
+      fit_percent: 85,
+      refreshComputed: true,
+    });
+
+    const rows = db.prepare(`SELECT * FROM matches WHERE cargo_id = 'cargo-refresh'`).all() as Array<Record<string, unknown>>;
+    expect(rows).toHaveLength(1);
+    expect(rows[0].tce_usd_per_day).toBe(15_000);
+    expect(rows[0].fit_percent).toBe(85);
+    // status preserved from first insert
+    expect(rows[0].status).toBe('saved');
+  });
+
+  it('refreshComputed COALESCE preserves existing worksheet_json when new value is null', () => {
+    const db = freshDb();
+    const original = JSON.stringify({ readiness: { verdict: 'ideal' } });
+    createMatch(db, { ...FULL_INPUT, cargo_id: 'cargo-ws', vessel_id: 'vessel-ws', worksheet_json: original });
+
+    createMatch(db, {
+      ...FULL_INPUT,
+      cargo_id: 'cargo-ws',
+      vessel_id: 'vessel-ws',
+      worksheet_json: null,
+      refreshComputed: true,
+    });
+
+    const rows = db.prepare(`SELECT worksheet_json FROM matches WHERE cargo_id = 'cargo-ws'`).all() as Array<{ worksheet_json: string | null }>;
+    expect(rows[0].worksheet_json).toBe(original);
+  });
+});
